        merged = try_concat(list(reversed(ra)), rb)
        if merged is not None:
            return merged
        merged = try_concat(list(reversed(ra)), list(reversed(rb)))
        if merged is not None:
            return merged
        return None

    def savings_key(i, j):
        ri, rj = routes[i], routes[j]
        if not ri or not rj:
            return -10**18
        if route_load(ri) + route_load(rj) > capacity:
            return -10**18
        base = route_cost(ri) + route_cost(rj)

        candidates = []
        candidates.append(ri + rj)
        candidates.append(ri + list(reversed(rj)))
        candidates.append(list(reversed(ri)) + rj)
        candidates.append(list(reversed(ri)) + list(reversed(rj)))

        best_gain = -10**18
        for merged in candidates:
            if route_load(merged) > capacity:
                continue
            gain = base - route_cost(merged)
            if gain > best_gain:
                best_gain = gain
        return best_gain

    def merge_phase():
        nonlocal routes
        for _ in range(6):
            if len(routes) <= hint:
                break
            if len(routes) <= 1:
                break

            best_i, best_j, best_merged, best_gain = None, None, None, 0
            m = len(routes)
            for i in range(m):
                for j in range(m):
                    if i == j:
                        continue
                    if len(routes) <= hint:
                        break
                    if route_load(routes[i]) + route_load(routes[j]) > capacity:
                        continue
                    gain = savings_key(i, j)
                    if gain <= 0:
                        continue
                    merged = attempt_merge(routes[i], routes[j])
                    if merged is None:
                        continue
                    if gain > best_gain or (gain == best_gain and (i, j) < (best_i, best_j)):
                        best_i, best_j, best_merged, best_gain = i, j, merged, gain
                if len(routes) <= hint:
                    break

            if best_merged is None:
                break

            i, j = best_i, best_j
            if i > j:
                routes.pop(i)
                routes.pop(j)
            else:
                routes.pop(j)
                routes.pop(i)
            routes.append(best_merged)

    merge_phase()

    # 2) Intra-route 2-opt (deterministic first-improvement with bounds)
    def two_opt_intra(r):
        n = len(r)
        if n < 4:
            return r
        iters = 0
        improved = True
        while improved and iters < 10:
            improved = False
            iters += 1
            base = route_cost(r)
            # classic deterministic first-improvement
            for i in range(n - 1):
                for k in range(i + 2, n):
                    newr = r[:i] + list(reversed(r[i:k + 1])) + r[k + 1:]
                    if route_cost(newr) + 1e-9 < base:
                        r = newr
                        n = len(r)
                        improved = True
                        break
                if improved:
                    break
        return r

    for idx in range(len(routes)):
        routes[idx] = two_opt_intra(routes[idx])

    # 3) Inter-route relocate: move single customer between routes if feasible and improves cost
    def relocate_phase():
        nonlocal routes
        for _ in range(4):
            improved_any = False
            loads = [route_load(r) for r in routes]
            costs = [route_cost(r) for r in routes]
            m = len(routes)
            for i in range(m):
                ri = routes[i]
                if not ri:
                    continue
                if len(ri) <= 1:
                    continue
                for pos in range(len(ri)):
                    cust = ri[pos]
                    best = None  # (delta, j, insert_pos, new_route_j, new_route_i)
                    for j in range(m):
                        if j == i:
                            continue
                        if loads[j] + demands[cust] > capacity:
                            continue
                        rj = routes[j]
                        new_ri = ri[:pos] + ri[pos + 1:]
                        base = costs[i] + costs[j]
                        # try insertion positions
                        for ins in range(len(rj) + 1):
                            if ins == 0:
                                new_rj = [cust] + rj
                            elif ins == len(rj):
                                new_rj = rj + [cust]
                            else:
                                new_rj = rj[:ins] + [cust] + rj[ins:]
                            new_cost = route_cost(new_ri) + route_cost(new_rj)
                            delta = base - new_cost
                            if delta > 1e-9:
                                if best is None or delta > best[0] or (delta == best[0] and (j, ins) < (best[1], best[2])):
                                    best = (delta, j, ins, new_rj, new_ri)
                    if best is not None:
                        delta, j, ins, new_rj, new_ri = best
                        routes[i] = new_ri
                        routes[j] = new_rj
                        loads[i] = route_load(new_ri)
                        loads[j] = route_load(new_rj)
                        costs[i] = route_cost(new_ri)
                        costs[j] = route_cost(new_rj)
                        improved_any = True
                        if not routes[i]:
                            routes.pop(i)
                        break
                if improved_any:
                    break
            if not improved_any:
                break

    relocate_phase()

    routes = [r for r in routes if r]
    return routes
